vertexShader:
attribute vec4 aSeed; uniform float uTime; uniform vec3 uCam; varying float vEmber; varying float vA;
void main() {
  vec3 box = vec3(90., 46., 90.);
  float ember = step(.93, aSeed.w);
  vec3 drift = ember > .5 ? vec3(.011, .034, .006) : vec3(.016, -.011, .009);                // ash falls and drifts, embers rise
  vec3 q = fract(aSeed.xyz + drift * uTime * (.6 + aSeed.w * .8) + vec3(sin(uTime * .7 + aSeed.w * 40.) * .004, 0., cos(uTime * .5 + aSeed.x * 30.) * .004));
  vec3 w = uCam + (fract(q - uCam / box + .5) - .5) * box;                                // wrapped around the camera
  vec4 mv = viewMatrix * vec4(w, 1.); gl_Position = projectionMatrix * mv;
  float d = -mv.z;
  gl_PointSize = clamp((ember > .5 ? .09 : .05 + aSeed.w * .05) * projectionMatrix[1][1] * 400. / max(d, .1), 1., 5.);
  vEmber = ember; vA = smoothstep(46., 20., d) * smoothstep(2.5, 5., d) * (ember > .5 ? .5 + .5 * sin(uTime * 6. + aSeed.y * 60.) : 1.);
}

fragmentShader:
varying float vEmber; varying float vA;
void main() { float r = length(gl_PointCoord - .5); if (r > .5) discard;
  vec3 c = vEmber > .5 ? vec3(2.2, .8, .2) : vec3(.16, .15, .15);
  gl_FragColor = vec4(c, (1. - smoothstep(.2, .5, r)) * vA * (vEmber > .5 ? 1. : .55));
  #include <colorspace_fragment>
}
